cd ~/measurement_env && menv python -c "
import sys; sys.path.insert(0, 'hera/models/tetralayer_fs_count')
import fs_count_b0 as M
import numpy as np
for n in (1.8e12, 2.2e12, 2.6e12, 3.0e12, -0.9e12):
    try:
        ef, orb = M.abab_fs(n*1e4)
        fs = [round(f,2) for f,k in orb]
        tot = sum(f for f,k in orb)
        print(f'n={n/1e12:+.2f}e12  ABAB orbits F = {fs}  sum={tot:.2f}')
    except Exception as e:
        print(f'n={n/1e12:+.2f}e12  ABAB -> {type(e).__name__}: {e}')
    try:
        out = M.abca_fs(n*1e4)
        print(f'                 ABCA -> EF={out[0]:.4f} topo={out[1]} ncomp={out[2]} nfreq={out[3]} F={out[4]:.2f}')
    except Exception as e:
        print(f'                 ABCA -> {type(e).__name__}: {e}')
" 2>&1 | tail -20
